// src/superembedder/witness_build_generation.cpp -- sec 8 C31(ii)
// (SEMB_WITNESS_DETACHED_LINK, `Claude/Plans/SuperEmbedder_Plan.md` sec
// 4.4d item 2): the library's own C ABI accessor for this build's
// per-configure build-generation token. The token itself is generated by
// CMake at configure time (cmake/templates/semb_witness_build_generation.h.in,
// SEMB_WITNESS_BUILD_GENERATION_TOKEN) into a header compiled into BOTH
// this library and witness_main.cpp -- identical bytes if and only if
// both were configured together. This accessor returns the LIBRARY's own
// compiled-in copy, read from its own compiled object, never from a file
// -- the witness compares this against its OWN compiled-in copy at
// process start, before computing anything (sec 4.4d item 2). This is the
// only new product code among the four items sec 4.4d specifies for this
// slice; everything else reuses an existing mechanism (C31(i)) or is a
// test-only change.
#include "superembedder/witness_abi.h"

#include <cstring>

#include "semb_witness_build_generation.h"

extern "C" void semb_library_build_generation(char out_token[32]) {
  // SEMB_WITNESS_BUILD_GENERATION_TOKEN is a 32-hex-character string
  // literal (33 bytes including its own trailing NUL) -- copy exactly the
  // 32 hex characters, matching witness_main.cpp's own 32-byte memcmp.
  std::memcpy(out_token, SEMB_WITNESS_BUILD_GENERATION_TOKEN, 32);
}
